package com.mmpantry.app;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatDelegate;
public class MainActivity extends Activity{LinearLayout box;public void onCreate(Bundle b){super.onCreate(b);boolean dark=getSharedPreferences("mm_settings",0).getBoolean("dark",false);AppCompatDelegate.setDefaultNightMode(dark?AppCompatDelegate.MODE_NIGHT_YES:AppCompatDelegate.MODE_NIGHT_NO);render();}void render(){box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(36,58,36,28);box.setBackgroundColor(Ui.background(this));TextView title=Ui.text(this,"MM Pantry",34);box.addView(title);TextView line=Ui.text(this,"Made with love from your pantry.",18);line.setTextColor(Ui.secondary(this));box.addView(line);TextView intro=Ui.text(this,"A little Spanish sun, Italian ease, and less food waste.",15);intro.setTextColor(Ui.secondary(this));box.addView(intro);add("YOUR PANTRY",PantryActivity.class);add("SUGGESTED RECIPES",RecipesActivity.class);add("SETTINGS",SettingsActivity.class);setContentView(box);}void add(String s,final Class<?> c){Button x=new Button(this);x.setText(s);x.setTextColor(android.graphics.Color.WHITE);x.setBackgroundColor(Ui.GOLD);x.setOnClickListener(v->startActivity(new Intent(this,c)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,ViewGroup.LayoutParams.WRAP_CONTENT);p.setMargins(0,24,0,0);box.addView(x,p);}}
